package com.vayunmathur.sdk.controller

import com.vayunmathur.e2ee.Hkdf
import java.security.MessageDigest
import java.security.SecureRandom
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Everything derived from the one 32-byte session secret.
 *
 * The secret is generated by the phone and sealed to the TV's ML-KEM public key, so it is the only
 * thing that crosses the wire; every key below is expanded from it by HKDF-SHA256 with a distinct
 * `info` string. Nothing is ever transmitted, which means a wrong derivation on either side shows
 * up as undecryptable frames rather than as a rejected message.
 *
 * **No Android or PQC dependency**: this whole file runs on the JVM, which is what makes the pairing
 * rules testable without a TV. Sealing the secret stays in `:library:e2ee-p2p` precisely so that the
 * native ML-KEM library stays out of here. The `info` prefix is namespaced to this SDK so its
 * output can never collide with `:cast:protocol`'s.
 */
class ControllerKeys private constructor(secret: ByteArray) {

    /** AES-256-GCM key for the channel, from `SEALED_SECRET` onward. */
    val control: ByteArray = derive(secret, "control", CONTROL_KEY_BYTES)

    /** HMAC key for the six-digit pair proof. */
    private val pairKey: ByteArray = derive(secret, "pair", CONTROL_KEY_BYTES)

    /** HMAC key for proving possession of a remembered device key. */
    private val deviceKeyProofKey: ByteArray = derive(secret, "device", CONTROL_KEY_BYTES)

    /**
     * `HMAC(HKDF(secret, "pair"), code ‖ transcript)`.
     *
     * Binding the code to the transcript is what makes six digits sufficient: the transcript covers
     * the TV's public bundle, so a man in the middle - which necessarily substituted its own bundle
     * - is proving a transcript it did not create, and cannot. Without that binding, six digits
     * would be six digits of entropy against an attacker who can replay; with it, the code only has
     * to survive the online attempt limit the host enforces.
     */
    fun pairProof(code: String, transcript: ByteArray): ByteArray =
        hmac(pairKey, code.toByteArray(Charsets.UTF_8) + transcript)

    /**
     * The same shape for a device the user already paired: possession of [deviceKey] replaces the
     * code, so a second session shows nothing on screen.
     */
    fun deviceProof(deviceKey: ByteArray, transcript: ByteArray): ByteArray =
        hmac(deviceKeyProofKey, deviceKey + transcript)

    companion object {
        const val SECRET_BYTES = 32
        private const val CONTROL_KEY_BYTES = 32

        /** Namespaced so this secret can never collide with another feature's HKDF output. */
        private const val INFO_PREFIX = "com.vayunmathur.sdk.controller/"

        fun of(secret: ByteArray): ControllerKeys {
            require(secret.size == SECRET_BYTES) {
                "the session secret is $SECRET_BYTES bytes; got ${secret.size}"
            }
            return ControllerKeys(secret)
        }

        /** A fresh session secret. Generated by the phone, once per session. */
        fun newSecret(random: SecureRandom = SecureRandom()): ByteArray =
            ByteArray(SECRET_BYTES).also { random.nextBytes(it) }

        private fun derive(secret: ByteArray, purpose: String, length: Int): ByteArray =
            Hkdf.derive(secret, "$INFO_PREFIX$purpose".toByteArray(Charsets.UTF_8), length)

        private fun hmac(key: ByteArray, data: ByteArray): ByteArray =
            Mac.getInstance("HmacSHA256")
                .apply { init(SecretKeySpec(key, "HmacSHA256")) }
                .doFinal(data)
    }
}

/** Whether a pair attempt was accepted, and what the user should be told if it was not. */
sealed interface ControllerPairResult {

    /** Paired. [deviceKey] is non-null when this was a code pairing and is what both ends persist. */
    data class Ok(val deviceKey: ByteArray?) : ControllerPairResult

    /**
     * Wrong proof.
     *
     * [codeChanged] means the attempt limit was reached and the code on screen has been replaced, so
     * the phone has to say "look at the TV again" rather than "try again".
     */
    data class Wrong(val attemptsLeft: Int, val codeChanged: Boolean) : ControllerPairResult
}

/**
 * The host's side of trust: the code on screen, the attempt limit, and proof verification.
 *
 * The attempt limit is what makes six digits defensible. Bound to the transcript, a proof cannot be
 * produced by a man in the middle at all (see [ControllerKeys.pairProof]); the only attack left is
 * guessing, and one in a million per attempt with three attempts and then a fresh code is not a
 * guessing attack worth mounting.
 *
 * Pure, so all of it - correct code, wrong code, lockout, and a remembered device - is a JVM test.
 * [newCode] is injectable for exactly that reason.
 */
class ControllerPairingGate(private val newCode: () -> String = { ControllerPairCode.random() }) {

    /** The six digits currently on screen. */
    var code: String = newCode()
        private set

    var attemptsLeft: Int = ControllerPairCode.MAX_ATTEMPTS
        private set

    /**
     * Verify a proof of the displayed code.
     *
     * On success a fresh device key is minted and returned, so later sessions can skip the code
     * entirely. On the third failure the code is thrown away and a new one generated; anything the
     * attacker learned about the old one is worth nothing.
     */
    fun verifyCode(keys: ControllerKeys, transcript: ByteArray, proof: ByteArray): ControllerPairResult {
        val expected = keys.pairProof(code, transcript)
        if (proofsMatch(expected, proof)) {
            reset()
            return ControllerPairResult.Ok(newDeviceKey())
        }
        attemptsLeft--
        if (attemptsLeft > 0) return ControllerPairResult.Wrong(attemptsLeft, codeChanged = false)
        reset()
        return ControllerPairResult.Wrong(attemptsLeft = ControllerPairCode.MAX_ATTEMPTS, codeChanged = true)
    }

    /**
     * Verify a proof of possession of a remembered [deviceKey].
     *
     * No attempt limit and no lockout: [deviceKey] is 32 random bytes, so there is nothing here worth
     * rate-limiting, and locking out on failure would let anyone on the LAN deny a paired phone
     * access by sending rubbish. A failure just means this phone is not the one we remember, and it
     * falls back to the code.
     */
    fun verifyDevice(
        keys: ControllerKeys,
        transcript: ByteArray,
        deviceKey: ByteArray,
        proof: ByteArray,
    ): ControllerPairResult =
        if (proofsMatch(keys.deviceProof(deviceKey, transcript), proof)) {
            // Nothing new to persist - the phone already holds the key it just proved.
            ControllerPairResult.Ok(deviceKey = null)
        } else {
            ControllerPairResult.Wrong(attemptsLeft = attemptsLeft, codeChanged = false)
        }

    /** Put a new code on screen, e.g. when a session ends without pairing. */
    fun reset() {
        code = newCode()
        attemptsLeft = ControllerPairCode.MAX_ATTEMPTS
    }

    companion object {
        const val DEVICE_KEY_BYTES = 32

        /** The long-term secret a paired phone keeps. Random, never derived from the code. */
        fun newDeviceKey(random: SecureRandom = SecureRandom()): ByteArray =
            ByteArray(DEVICE_KEY_BYTES).also { random.nextBytes(it) }
    }
}

/**
 * The six digits the TV shows and the user types on the phone.
 *
 * Six is enough only because the proof is transcript-bound and the host limits attempts - see
 * [ControllerKeys.pairProof].
 */
object ControllerPairCode {

    const val DIGITS = 6

    /**
     * How many wrong codes before the displayed one is thrown away.
     *
     * Three, then a new code: this is what removes the offline-guessing objection to six digits, so
     * it is a correctness boundary rather than a nicety.
     */
    const val MAX_ATTEMPTS = 3

    private const val RANGE = 1_000_000

    fun random(random: SecureRandom = SecureRandom()): String =
        random.nextInt(RANGE).toString().padStart(DIGITS, '0')

    /** True when [entered] could be a code at all, so a typo is refused without an HMAC. */
    fun isWellFormed(entered: String): Boolean =
        entered.length == DIGITS && entered.all { it in '0'..'9' }
}

/**
 * The running hash of the handshake, up to and including `SEALED_SECRET`.
 *
 * Fed the **exact bytes that crossed the wire**, not re-encoded objects: JSON round-tripping is not
 * guaranteed to be byte-stable, and a transcript that differs by a key order is a transcript the two
 * ends disagree on - which would fail every pair attempt with no clue as to why.
 */
class ControllerTranscript {

    private val bodies = mutableListOf<ByteArray>()

    fun add(body: ByteArray) {
        bodies += body
    }

    fun value(): ByteArray {
        val digest = MessageDigest.getInstance("SHA-256")
        for (body in bodies) digest.update(body)
        return digest.digest()
    }
}

/** Constant-time comparison, so a wrong proof leaks nothing about how wrong it was. */
fun proofsMatch(a: ByteArray, b: ByteArray): Boolean = MessageDigest.isEqual(a, b)
